def display(name): return RENAME.get(name.strip().lower(), name.strip())
def classify(name):
    n = name.strip()
    if not n or EXCLUDE.match(n): return None
    base = re.sub(r'\s*\(.*?\)\s*', ' ', n).strip()
    ov = OVERRIDE.get(n.lower())
    if ov:
        w = 'fresh' if ov in ('Frogs and toads',) else ''
        if ov in ('Molluscs',): w = 'salt'
        if ov == 'Fish': w = 'fresh' if FRESH.search(base) else 'salt'
        return ('Animals', ov, w)
    if re.search(r'saur|raptor', base, re.I) or re.search(r'(doodle|poo$|terrier|spaniel|retriever|shepherd|hound|dog$)', base, re.I) and not re.search(r'\b(snake|frog|moth)\b', base, re.I): pass
    words = re.findall(r"[A-Za-z’'-]+", base.lower())
    if len(words) >= 2 and words[-1] in HEAD and not re.search(r'saur|raptor|dog\b|hound|terrier|spaniel|retriever|poodle|doodle|shepherd', base, re.I):
        cls = HEAD[words[-1]]; w = ''
        if cls in ('Fish', 'Crustaceans', 'Molluscs'): w = 'fresh' if FRESH.search(base) and not SALT.search(base) else ('salt' if SALT.search(base) else 'both')
        elif cls == 'Sharks and rays' or cls == 'Whales, dolphins and seals': w = 'salt'
        elif cls in ('Frogs and toads',): w = 'fresh'
        return ('Animals', cls, w)
    for kingdom, cls, rx in OTHER:
        if rx.search(base): return (kingdom, cls, '')
    for cls, rx, w in RULES:
        if rx.search(base):
            if cls == 'Fish' or cls in ('Crustaceans', 'Molluscs') or w == 'both':
                water = 'fresh' if FRESH.search(base) and not SALT.search(base) else ('salt' if SALT.search(base) else 'both')
                if cls in ('Waterbirds and seabirds', 'Crocodiles and alligators'): water = ''
            else: water = w
            return ('Animals', cls, water)
    return ('Animals', 'Other animals', '')
def load():
    seen = set(); out = []
    for l in open(os.path.join(HERE, 'data', 'animals_source.txt'), encoding='utf8').read().split('\n'):
        l = l.strip()
        if not l or l.lower() in seen: continue
        seen.add(l.lower()); out.append(l)
    return out
if __name__ == '__main__':
    import collections
    c = collections.Counter(); oth = []
    for n in load():
        r = classify(n)
        if r is None: continue
        c[(r[0], r[1], r[2])] += 1
        if r[1] == 'Other animals': oth.append(n)
    for k, v in sorted(c.items(), key=lambda x: -x[1]): print(v, k)
    print(len(oth), oth[:80])
